mapper.sql:
WHERE i.status = 'ACTIVE' AND i.visibility = 'PUBLIC'
AND i.country = #{country}
AND ( LOCATE(#{keyword}, i.title) > 0 OR LOCATE(#{keyword}, i.summary) > 0 OR LOCATE(#{keyword}, i.country) > 0 OR LOCATE(#{keyword}, i.city) > 0 OR LOCATE(#{keyword}, i.continent) > 0 OR LOCATE(#{keyword}, CAST(i.traveler_count AS CHAR)) > 0 OR LOCATE(#{keyword}, CAST(i.total_budget AS CHAR)) > 0 OR LOCATE(#{keyword}, u.nickname) > 0 )
AND (
DATEDIFF(i.end_date, i.start_date) >= 5
DATEDIFF(i.end_date, i.start_date) = (CAST(#{duration} AS SIGNED) - 1)
)
AND (
i.total_budget <= 1000000
i.total_budget > 5000000
( i.total_budget > (CAST(#{budget} AS SIGNED) - 1) * 1000000 AND i.total_budget <= CAST(#{budget} AS SIGNED) * 1000000 )
)
AND (
i.traveler_count >= 6
i.traveler_count = #{traveler}
)
